import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('VarelaRound');
import { noise2D } from "@remotion/noise";

// Module-level font loading — delayRender/continueRender handled internally
const { fontFamily } = loadFont();



export type NeonSignProps = Record<string, any>;

// --- Animation Logic Helpers ---

const getCharIntensity = (frame: number, i: number, totalChars: number) => {
  if (totalChars === 0) return 0;
  
  // Power-off state
  if (frame < 22) return 0;
  
  // Global stutter on trigger
  if (frame >= 22 && frame < 30) {
    return random(`stutter-${frame}`) > 0.5 ? 0.4 : 0;
  }
  
  // Dramatic pause
  if (frame >= 30 && frame < 35) return 0;
  
  // Surge sequence
  const surgeStartFrame = 35;
  const surgeDuration = 20;
  const charTurnOnFrame = surgeStartFrame + (i / totalChars) * surgeDuration;

  if (frame < charTurnOnFrame) return 0;

  // Localized flicker right as the letter ignites
  const framesSinceOn = frame - charTurnOnFrame;
  if (framesSinceOn < 5) {
    return random(`settle-${frame}-${i}`) > 0.3 ? 1 : 0.4;
  }

  // Steady hum/breathing (fluctuates between 0.9 and 1.0)
  const hum = 0.95 + 0.05 * noise2D(`hum-${i}`, frame * 0.05, 0);
  return hum;
};

const getGlobalIntensity = (frame: number) => {
  if (frame < 22) return 0;
  if (frame >= 22 && frame < 30) return random(`global-${frame}`) > 0.5 ? 0.3 : 0;
  if (frame >= 30 && frame < 35) return 0;
  if (frame >= 35) {
    return interpolate(frame, [35, 55], [0, 1], { extrapolateRight: "clamp" });
  }
  return 1;
};

// --- Sub-components ---

const PullString: React.FC<{ frame: number; s: number }> = ({ frame, s }) => {
  let length = 180 * s;

  if (frame >= 10 && frame < 22) {
    // Pulling down
    length = interpolate(frame, [10, 22], [180 * s, 300 * s], {
      easing: Easing.inOut(Easing.quad),
    });
  } else if (frame >= 22) {
    // Snapping back up
    const springVal = spring({
      frame: frame - 22,
      fps: 30,
      config: { damping: 10, stiffness: 150, mass: 1.5 },
    });
    length = interpolate(springVal, [0, 1], [300 * s, 180 * s]);
  }

  // Slight sway from the motion
  const swing =
    frame > 10 && frame < 60 ? Math.sin((frame - 10) * 0.4) * 3 : 0;

  return (
    <div
      style={{
        position: "absolute",
        top: "95%",
        left: "50%",
        width: 6 * s,
        height: length,
        background: "linear-gradient(to right, #111, #444, #111)",
        zIndex: -1,
        transformOrigin: "top center",
        transform: `translateX(-50%) rotate(${swing}deg)`,
        borderRadius: 3 * s,
        boxShadow: `inset ${2 * s}px 0 ${2 * s}px rgba(0,0,0,0.5)`,
      }}
    >
      <div
        style={{
          position: "absolute",
          bottom: -20 * s,
          left: "50%",
          transform: "translateX(-50%)",
          width: 24 * s,
          height: 40 * s,
          borderRadius: 12 * s,
          background: "linear-gradient(to right, #222, #555, #222)",
          border: `${2 * s}px solid #111`,
          boxShadow: `0 ${4 * s}px ${10 * s}px rgba(0,0,0,0.5)`,
        }}
      />
    </div>
  );
};

const NeonChar: React.FC<{
  char: string;
  intensity: number;
  neonColor: string;
  s: number;
  fontSize: number;
  isLast?: boolean;
  frame?: number;
}> = ({ char, intensity, neonColor, s, fontSize, isLast, frame }) => {
  const isSpace = char === " ";
  if (isSpace) return <span style={{ width: fontSize * 0.27, display: "inline-block" }} />;

  // Dim glass tube color when off, bright white-hot core when on
  const tubeRed = interpolate(intensity, [0, 0.5, 1], [70, 255, 255]);
  const tubeGreen = interpolate(intensity, [0, 0.5, 1], [70, 255, 255]);
  const tubeBlue = interpolate(intensity, [0, 0.5, 1], [70, 255, 255]);
  const tubeColor = `rgb(${tubeRed}, ${tubeGreen}, ${tubeBlue})`;

  const coreGlowOpacity = interpolate(intensity, [0, 0.5, 1], [0, 0.8, 1]);

  return (
    <span
      style={{
        position: "relative",
        display: "inline-block",
        fontSize: fontSize,
        fontWeight: "bold",
        lineHeight: 1,
        textTransform: "uppercase",
        transition: "none",
      }}
    >
      {/* Bloom / Glow Layer */}
      <span
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          color: "transparent",
          opacity: intensity,
          textShadow: `
            0 0 ${fontSize * 0.045}px ${neonColor},
            0 0 ${fontSize * 0.09}px ${neonColor},
            0 0 ${fontSize * 0.18}px ${neonColor},
            0 0 ${fontSize * 0.36}px ${neonColor},
            0 0 ${fontSize * 0.54}px ${neonColor}
          `,
          zIndex: 1,
          transition: "none",
        }}
      >
        {char}
      </span>

      {/* Physical Tube Layer */}
      <span
        style={{
          position: "relative",
          color: tubeColor,
          textShadow:
            intensity > 0.1
              ? `
            0 0 ${fontSize * 0.018}px rgba(255,255,255,${coreGlowOpacity}),
            0 0 ${fontSize * 0.036}px rgba(255,255,255,${coreGlowOpacity})
          `
              : "none",
          zIndex: 2,
          transition: "none",
        }}
      >
        {char}
      </span>

      {/* String Switch attached to the bottom of the very last letter ("S" in default case) */}
      {isLast && frame !== undefined && <PullString frame={frame} s={s} />}
    </span>
  );
};

const SignText: React.FC<{
  line1: string;
  line2: string;
  frame: number;
  neonColor: string;
  s: number;
  hasString: boolean;
}> = ({ line1, line2, frame, neonColor, s, hasString }) => {
  const totalChars = line1.length + line2.length;
  let charIndex = 0;

  const renderLine = (text: string, isLastLine: boolean) => {
    const chars = text.split("");
    // Render the first line significantly bigger
    const fontSize = isLastLine ? 190 * s : 310 * s;

    return (
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          justifyContent: "center",
          flexWrap: "nowrap",
          whiteSpace: "nowrap",
        }}
      >
        {chars.map((char, i) => {
          const currentIdx = charIndex++;
          const intensity = getCharIntensity(frame, currentIdx, totalChars);
          const isAbsoluteLast = isLastLine && i === chars.length - 1;

          return (
            <NeonChar
              key={i}
              char={char}
              intensity={intensity}
              neonColor={neonColor}
              s={s}
              fontSize={fontSize}
              isLast={hasString && isAbsoluteLast}
              frame={frame}
            />
          );
        })}
      </div>
    );
  };

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 20 * s,
      }}
    >
      {renderLine(line1, false)}
      {renderLine(line2, true)}
    </div>
  );
};

// --- Main Component ---

const NeonSignAnimation: React.FC<NeonSignProps> = ({
  line1Text = "24/7",
  line2Text = "ACCESS",
  neonColor = "#00f0ff", // Updated to Neon Blue by default
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 8,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const globalIntensity = getGlobalIntensity(frame);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        overflow: "hidden",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Background Soft Bloom */}
      <div
        style={{
          position: "absolute",
          width: width * 1.5,
          height: height * 1.5,
          background: `radial-gradient(circle at center, ${neonColor} 0%, transparent 60%)`,
          opacity: interpolate(globalIntensity, [0, 1], [0, 0.12]),
          zIndex: 0,
          mixBlendMode: "screen",
          transition: "none",
        }}
      />

      {/* Main Sign Assembly */}
      <div
        style={{
          position: "relative",
          zIndex: 10,
          transform: `translateY(${-40 * s}px)`,
          transition: "none",
        }}
      >
        <SignText
          line1={line1Text}
          line2={line2Text}
          frame={frame}
          neonColor={neonColor}
          s={s}
          hasString={true}
        />

        {/* Floor Reflection */}
        <div
          style={{
            position: "absolute",
            top: "100%",
            left: 0,
            right: 0,
            marginTop: 40 * s,
            transform: "scaleY(-1)",
            opacity: interpolate(globalIntensity, [0, 1], [0, 0.25]),
            filter: `blur(${40 * s}px)`,
            zIndex: -1,
            // Fades the reflection smoothly into the background
            WebkitMaskImage: "linear-gradient(to top, rgba(0,0,0,1) 0%, rgba(0,0,0,0) 100%)",
            transition: "none",
          }}
        >
          <SignText
            line1={line1Text}
            line2={line2Text}
            frame={frame}
            neonColor={neonColor}
            s={s}
            hasString={false}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default NeonSignAnimation;